package com.epicontrol.epicontrol.service;

import com.epicontrol.epicontrol.model.EpisModel;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.ParameterizedTypeReference;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.RestTemplate;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Service
public class EpisService {

    @Value("${api.base.url}") // Ex: http://localhost:8081/api
    private String apiBaseUrl;

    private final RestTemplate restTemplate = new RestTemplate();

    /**
     * Cria os cabeçalhos HTTP para a requisição, incluindo o token de autorização.
     * @param token O token JWT ou Firebase ID Token.
     * @return HttpHeaders configurado.
     */
    private HttpHeaders createAuthHeaders(String token) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        // CORREÇÃO: Adiciona o prefixo "Bearer " ao token.
        headers.set("Authorization", "Bearer " + token);
        return headers;
    }

    public List<EpisModel> listarEpis(String token) {
        String url = apiBaseUrl + "/epis";
        HttpEntity<String> entity = new HttpEntity<>(createAuthHeaders(token));

        try {
            ResponseEntity<List<EpisModel>> response = restTemplate.exchange(
                url,
                HttpMethod.GET,
                entity,
                new ParameterizedTypeReference<List<EpisModel>>() {}
            );
            return response.getBody();
        } catch (HttpClientErrorException e) {
            // Lança uma exceção mais clara para ser tratada no controller ou globalmente.
            throw new RuntimeException("Falha ao listar EPIs: " + e.getStatusCode() + " - " + e.getResponseBodyAsString(), e);
        }
    }

    public void criarEpi(EpisModel epi, String token) {
        String url = apiBaseUrl + "/epis";
        HttpEntity<EpisModel> entity = new HttpEntity<>(epi, createAuthHeaders(token));
        try {
            restTemplate.postForEntity(url, entity, String.class);
        } catch (HttpClientErrorException e) {
            throw new RuntimeException("Falha ao criar EPI: " + e.getResponseBodyAsString(), e);
        }
    }

    public void editarEpi(String id, EpisModel epi, String token) {
        String url = apiBaseUrl + "/epis/" + id;
        HttpEntity<EpisModel> entity = new HttpEntity<>(epi, createAuthHeaders(token));
        try {
            restTemplate.exchange(url, HttpMethod.PUT, entity, String.class);
        } catch (HttpClientErrorException e) {
            throw new RuntimeException("Falha ao editar EPI: " + e.getResponseBodyAsString(), e);
        }
    }

    public void deletarEpi(String id, String token) {
        String url = apiBaseUrl + "/epis/" + id;
        HttpEntity<String> entity = new HttpEntity<>(createAuthHeaders(token));
        try {
            restTemplate.exchange(url, HttpMethod.DELETE, entity, String.class);
        } catch (HttpClientErrorException e) {
            throw new RuntimeException("Falha ao deletar EPI: " + e.getResponseBodyAsString(), e);
        }
    }

    public EpisModel getEpiById(String id, String token) {
        String url = apiBaseUrl + "/epis/" + id;
        HttpEntity<String> entity = new HttpEntity<>(createAuthHeaders(token));
        try {
            ResponseEntity<EpisModel> response = restTemplate.exchange(
                url,
                HttpMethod.GET,
                entity,
                EpisModel.class
            );
            return response.getBody();
        } catch (HttpClientErrorException e) {
            throw new RuntimeException("Falha ao buscar EPI por ID: " + e.getResponseBodyAsString(), e);
        }
    }
}
